     1	import java.math.BigDecimal;
     2	import java.util.List;
     3	
     4	/**
     5	 * A policy the office has written: the {@link Coverage} it was written over and
     6	 * the {@link PayoutCap} it was written under.
     7	 *
     8	 * Settling an incident against the policy is this policy's decision, not the
     9	 * protocol's, and all it decides is how the three parties to a settlement meet:
    10	 * the coverage says which covered item a reported damage is settled on, the
    11	 * {@link ClaimPolicy} says what that one damage earns, and the cap says how much
    12	 * of it is actually paid. So the deductible is borne once per damage reported
    13	 * and the cap is consumed in the order the damages are reported.
    14	 */
    15	public class Policy {
    16	
    17	    private final Coverage coverage;
    18	    private final PayoutCap payoutCap;
    19	
    20	    /**
    21	     * The office writes a policy over the items a customer brings: what it
    22	     * insures them for is the {@link PriceList}'s to state, and the cap that
    23	     * insurance sum earns is the cap's own rule. Premium modifiers are no part
    24	     * of it, which is why the policy is written from the covered items and never
    25	     * from the premium quoted for them.
    26	     */
    27	    public static Policy covering(List<InsuredItem> insuredItems, PriceList priceList) {
    28	        return new Policy(Coverage.of(insuredItems),
    29	                PayoutCap.forInsuranceSum(priceList.insuranceSum(insuredItems)));
    30	    }
    31	
    32	    private Policy(Coverage coverage, PayoutCap payoutCap) {
    33	        this.coverage = coverage;
    34	        this.payoutCap = payoutCap;
    35	    }
    36	
    37	    /**
    38	     * What the office pays for one reported incident: the sum of what each
    39	     * damage reported is settled for, settled in the order reported so that the
    40	     * cap is consumed in that order.
    41	     */
    42	    public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
    43	        BigDecimal paid = BigDecimal.ZERO;
    44	        for (Damage damage : damages) {
    45	            paid = paid.add(settleOne(damage, claimPolicy));
    46	        }
    47	        return paid;
    48	    }
    49	
    50	    /**
    51	     * What one reported damage is actually paid: the coverage says which covered
    52	     * item it is settled on, the claim rules say what that damage earns on that
    53	     * item's terms, and the cap pays what it still allows of it.
    54	     *
    55	     * Every damage reported is settled here on its own, which is why a second
    56	     * damage of a kind already damaged bears the deductible again and draws on
    57	     * the cap the first one has already reduced. Settling an incident as a whole
    58	     * instead — one deductible for the incident, or the incident's total tested
    59	     * against the cap in one go — would be a revision of this one sentence.
    60	     */
    61	    private BigDecimal settleOne(Damage damage, ClaimPolicy claimPolicy) {
    62	        InsuredItem damagedItem = coverage.itemDamagedBy(damage);
    63	        return payoutCap.pay(claimPolicy.reimbursementFor(damage.amount(), damagedItem));
    64	    }
    65	
    66	    public BigDecimal remainingCap() {
    67	        return payoutCap.remaining();
    68	    }
    69	}
===== ClaimPolicy.java =====
     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The MHPCO claim rules: what the office reimburses for a damage report against
     5	 * a policy, after the deductible and within the policy's payout cap.
     6	 *
     7	 * Two decisions the office revises on their own schedules meet here, in the
     8	 * order the specification fixes: its clause book states how much of a damage
     9	 * counts as reimbursable at all, and only then is the deductible borne. A new
    10	 * clause or a revised threshold is the clause book's business; repricing the
    11	 * deductible is this rule's.
    12	 *
    13	 * A payout is a payment out of the office, so its fraction of a G is rounded in
    14	 * the office's favor by {@link InOfficesFavor}.
    15	 */
    16	public class ClaimPolicy {
    17	
    18	    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = new BigDecimal("100");
    19	    private static final BigDecimal UNRULY_ITEM_REIMBURSEMENT_RATE = new BigDecimal("0.5");
    20	
    21	    /**
    22	     * The office reimburses the reimbursable part of a damage less the
    23	     * deductible, never below nothing.
    24	     */
    25	    public BigDecimal reimbursementFor(BigDecimal damageAmount, InsuredItem damagedItem) {
    26	        return InOfficesFavor.payment(reimbursableDamageUnderClauses(damageAmount, damagedItem)
    27	                .subtract(DEDUCTIBLE_PER_DAMAGE)
    28	                .max(BigDecimal.ZERO));
    29	    }
    30	
    31	    /**
    32	     * How much of a damage the office's clause book lets it count as
    33	     * reimbursable, read from the damaged item and settled before the
    34	     * deductible. The high-enchantment clause reimburses an unruly item's damage
    35	     * at a reduced rate; a damage no clause speaks to counts in full.
    36	     *
    37	     * The office's second clause, that damage to an item of dragon material is
    38	     * fully reimbursed, is absent here deliberately rather than by oversight: in
    39	     * every case the specification states it grants exactly what a damage no
    40	     * clause speaks to already earns. Below the unruly threshold it reimburses in
    41	     * full, which is the default; at or above it the specification gives the
    42	     * reduced rate precedence. So the clause never changes a reimbursement, and
    43	     * the office does not record an item's material at all. A revision that gave
    44	     * dragon material its own rate, or precedence over the high-enchantment
    45	     * clause, would be the first to make the material worth recording.
    46	     */
    47	    private static BigDecimal reimbursableDamageUnderClauses(BigDecimal damageAmount,
    48	            InsuredItem damagedItem) {
    49	        if (damagedItem.isTooUnrulyToReimburseInFull()) {
    50	            return damageAmount.multiply(UNRULY_ITEM_REIMBURSEMENT_RATE);
    51	        }
    52	        return damageAmount;
    53	    }
    54	}
===== PayoutCap.java =====
     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The limit on everything a policy will ever pay out, and how much of it is
     5	 * left. The office caps a policy at twice the insurance sum of the items it
     6	 * covers.
     7	 *
     8	 * What the cap is worth and what it has left are one decision revised on its
     9	 * own schedule: a revision to the multiple, or one that let the cap replenish,
    10	 * is this cap's business and touches no claim rule. Premium modifiers are no
    11	 * part of it, which is why a cap is opened from an insurance sum and never from
    12	 * a premium.
    13	 */
    14	class PayoutCap {
    15	
    16	    private static final BigDecimal CAP_MULTIPLE_OF_INSURANCE_SUM = new BigDecimal("2");
    17	
    18	    private BigDecimal remaining;
    19	
    20	    static PayoutCap forInsuranceSum(BigDecimal insuranceSum) {
    21	        return new PayoutCap(insuranceSum.multiply(CAP_MULTIPLE_OF_INSURANCE_SUM));
    22	    }
    23	
    24	    private PayoutCap(BigDecimal remaining) {
    25	        this.remaining = remaining;
    26	    }
    27	
    28	    /** Pays what the cap still allows of a desired payout and consumes that much of it. */
    29	    BigDecimal pay(BigDecimal desiredPayout) {
    30	        BigDecimal paid = desiredPayout.min(remaining);
    31	        remaining = remaining.subtract(paid);
    32	        return paid;
    33	    }
    34	
    35	    BigDecimal remaining() {
    36	        return remaining;
    37	    }
    38	}
