     9	import com.fasterxml.jackson.databind.JsonNode;
    10	import com.fasterxml.jackson.databind.ObjectMapper;
    11	import com.fasterxml.jackson.databind.node.ArrayNode;
    12	import com.fasterxml.jackson.databind.node.ObjectNode;
    13	
    14	/**
    15	 * Translates the JSON scenario protocol into MHPCO operations and back. The
    16	 * protocol field names are binding; what the office does with a step, and what
    17	 * it carries from one step to the next, is the {@link ClaimOffice}'s business.
    18	 */
    19	public class ClaimOfficeCli {
    20	
    21	    private static final ObjectMapper JSON = new ObjectMapper();
    22	
    23	    private static final int ACCEPTED = 0;
    24	    private static final int REJECTED = 1;
    25	
    26	    /**
    27	     * Reports the scenario's results, answering the exit status the office
    28	     * exits with: nothing but the results document on stdout when the office
    29	     * accepts the scenario.
    30	     */
    31	    public int report(InputStream scenario, PrintStream results, PrintStream rejection) {
    32	        try {
    33	            results.print(resultsFor(scenario));
    34	            return ACCEPTED;
    35	        } catch (RejectedScenario refusal) {
    36	            rejection.println(refusal.getMessage());
    37	            return REJECTED;
    38	        }
    39	    }
    40	
    41	    private String resultsFor(InputStream scenario) {
    42	        try {
    43	            JsonNode input = JSON.readTree(scenario);
    44	            ClaimOffice office =
    45	                    new ClaimOffice(input.get("customer").get("yearsWithMHPCO").asInt());
    46	            ObjectNode output = JSON.createObjectNode();
    47	            ArrayNode resultsNode = output.putArray("results");
    48	            JsonNode steps = input.get("steps");
    49	            for (int stepIndex = 0; stepIndex < steps.size(); stepIndex++) {
    50	                JsonNode step = steps.get(stepIndex);
    51	                if ("claim".equals(step.get("op").asText())) {
    52	                    writeSettlement(office.settleClaim(step.get("policy").asInt(), damages(step)),
    53	                            resultsNode.addObject());
    54	                    continue;
    55	                }
    56	                resultsNode.addObject().put("premium",
    57	                        office.quote(stepIndex, insuredItems(step)));
    58	            }
    59	            return JSON.writeValueAsString(output);
    60	        } catch (IOException e) {
    61	            throw new UncheckedIOException(e);
    62	        }
    63	    }
    64	
    65	    private static void writeSettlement(ClaimOffice.Settlement settlement, ObjectNode result) {
    66	        result.put("payout", settlement.payout().intValueExact());
    67	        result.put("remainingCap", settlement.remainingCap().intValueExact());
    68	    }
    69	
    70	    private static List<Damage> damages(JsonNode claimStep) {
    71	        List<Damage> damages = new ArrayList<>();
    72	        for (JsonNode damage : claimStep.get("incident").get("damages")) {
    73	            damages.add(new Damage(damage.get("itemType").asText(),
    74	                    new BigDecimal(damage.get("amount").asText())));
    75	        }
    76	        return damages;
    77	    }
    78	
    79	    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
    80	        List<InsuredItem> items = new ArrayList<>();
    81	        for (JsonNode item : quoteStep.get("items")) {
    82	            items.add(new InsuredItem(item.get("type").asText(),
    83	                    item.path("cursed").asBoolean(false),
    84	                    item.path("enchantment").asInt(0)));
    85	        }
    86	        return items;
    87	    }
    88	}
===== PriceList.java =====
     1	import java.math.BigDecimal;
     2	import java.util.LinkedHashMap;
     3	import java.util.List;
     4	import java.util.Map;
     5	import java.util.Set;
     6	
     7	/**
     8	 * The MHPCO price list: one published tariff row per insurable item type,
     9	 * stating what the office charges as that item's base premium and what it
    10	 * insures the item for. Main items are listed individually; every component
    11	 * shares one row, because the office prices and insures a rune exactly as it
    12	 * does a moonstone, and a building block of alike components is offered at a
    13	 * special rate.
    14	 *
    15	 * The block rate is the one tariff decision that is not a property of a single
    16	 * item: a block is a quantity of <em>alike</em> components, so the tariff also
    17	 * decides which items count as alike (see {@link #alikenessGroupOf}) and groups
    18	 * them before pricing. It groups for pricing only: the insured values are read
    19	 * per item, because an offer on what the office charges is no revaluation of
    20	 * what it insures.
    21	 *
    22	 * This is the office's tariff. It changes on its own schedule, independently of
    23	 * the modifier rules in {@link PremiumPolicy}.
    24	 */
    25	public class PriceList {
    26	
    27	    /**
    28	     * What the office charges and insures for one item type. The two figures
    29	     * are revised on their own schedules — a rate revision repricing premiums
    30	     * need not revalue the items — but they are published together, as one row
    31	     * of the price list, because they describe the same insured thing.
    32	     */
    33	    private record Tariff(BigDecimal basePremium, BigDecimal insuranceValue) {
    34	    }
    35	
    36	    /** Every component is charged and insured alike, whatever its type. */
    37	    private static final Tariff COMPONENT_TARIFF =
    38	            new Tariff(new BigDecimal("25"), new BigDecimal("250"));
    39	
    40	    /** The published price list: the item types the office insures, and at what. */
    41	    private static final Map<String, Tariff> TARIFF = Map.of(
    42	            "sword", new Tariff(new BigDecimal("100"), new BigDecimal("1000")),
    43	            "amulet", new Tariff(new BigDecimal("60"), new BigDecimal("600")),
    44	            "staff", new Tariff(new BigDecimal("80"), new BigDecimal("800")),
    45	            "potion", new Tariff(new BigDecimal("40"), new BigDecimal("400")),
    46	            "rune", COMPONENT_TARIFF,
    47	            "moonstone", COMPONENT_TARIFF);
    48	
    49	    /**
    50	     * Which of the insured types the office regards as components rather than
    51	     * main items. Only the block offer asks: a component's own figures are read
    52	     * from its tariff row like any other item's.
    53	     */
    54	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
    55	
    56	    /** A building block of exactly 3 alike components is offered at this rate. */
    57	    private static final BigDecimal COMPONENT_BLOCK_BASE_PREMIUM = new BigDecimal("60");
    58	    private static final int COMPONENT_BLOCK_SIZE = 3;
    59	
    60	    /**
    61	     * The insurance sum of a policy: the sum of its items' insurance values,
    62	     * each item valued on its own.
    63	     *
    64	     * This deliberately asks nothing about holdings, while
    65	     * {@link #policyBasePremium} prices alike items together. The two figures of
    66	     * a tariff row are read on different terms because the block rate is an
    67	     * offer on what the office <em>charges</em>, not a revaluation of what it
    68	     * <em>insures</em>: a block of 3 runes is charged 60 G but still insured for
    69	     * 3 x 250 G, so the cap it earns is untouched by the discount. Any future
    70	     * holding-dependent offer belongs in the premium fold alone; a revision that
    71	     * also revalued a holding would be the first to group items here.
    72	     */
    73	    public BigDecimal insuranceSum(List<InsuredItem> insuredItems) {
    74	        BigDecimal total = BigDecimal.ZERO;
    75	        for (InsuredItem insuredItem : insuredItems) {
    76	            total = total.add(tariffFor(insuredItem.type()).insuranceValue());
    77	        }
    78	        return total;
    79	    }
    80	
    81	    /**
    82	     * The base premium for all items a policy covers, alike items priced
    83	     * together because the block rate is an offer on a holding rather than on a
    84	     * single item. This is the one fold that groups: {@link #insuranceSum}
    85	     * values each item on its own, as the block offer leaves the insured values
    86	     * alone.
    87	     */
    88	    public BigDecimal policyBasePremium(List<InsuredItem> insuredItems) {
    89	        BigDecimal total = BigDecimal.ZERO;
    90	        for (Map.Entry<String, Integer> alikeItems : groupedByAlikeness(insuredItems).entrySet()) {
    91	            total = total.add(basePremium(alikeItems.getKey(), alikeItems.getValue()));
    92	        }
    93	        return total;
    94	    }
    95	
    96	    /**
    97	     * The base premium of one insured item on its own, which is what an
    98	     * item-specific surcharge such as the curse surcharge is charged on. A
    99	     * component priced within a block is not charged on its own.
   100	     */
   101	    public BigDecimal basePremium(InsuredItem insuredItem) {
   102	        return basePremium(insuredItem.type(), 1);
   103	    }
   104	
   105	    private static Map<String, Integer> groupedByAlikeness(List<InsuredItem> insuredItems) {
   106	        Map<String, Integer> counts = new LinkedHashMap<>();
   107	        for (InsuredItem insuredItem : insuredItems) {
   108	            counts.merge(alikenessGroupOf(insuredItem.type()), 1, Integer::sum);
   109	        }
   110	        return counts;
   111	    }
   112	
   113	    /**
   114	     * The office counts two items as alike when they are of exactly the same
   115	     * type, not merely of the same family: 2 runes and a moonstone are three
   116	     * loose components priced at 75 G, never a block, because a moonstone is not
   117	     * a rune. Widening "alike" to a family (rune-y, gemstone-y) would mean
   118	     * returning a family name here instead of the type itself.
   119	     */
   120	    private static String alikenessGroupOf(String itemType) {
   121	        return itemType;
   122	    }
   123	
   124	    /**
   125	     * The tariff row for an item type. The office insures only the items on its
   126	     * price list, so an item it does not recognize is no business of its own.
   127	     */
   128	    private static Tariff tariffFor(String itemType) {
   129	        Tariff tariff = TARIFF.get(itemType);
   130	        if (tariff == null) {
   131	            throw new RejectedScenario("the MHPCO does not insure items of type " + itemType);
   132	        }
